namespace Motion {

//------------------------------------------------------------------------------
// !Constants
//------------------------------------------------------------------------------

// CW-primary hand-off
// TODO: guess; tune via experiments
constexpr double kDefaultHandoffBand = 0.0175;  // ~1 deg (rad)

// Calibration limits
// TODO: guesses; tune via experiments
constexpr double kMaxCalibrationAngle = 1.4;  // |θ| limit, ~80 deg (rad)
constexpr double kMinAngleSeparation = 0.2;   // |θ_b − θ_a|, ~11 deg (rad)
constexpr double kFrictionMinWindow = 0.105;  // incl. unsampled ends (rad)

//------------------------------------------------------------------------------
// !Types
//------------------------------------------------------------------------------

/**
 * @brief What the counterweight (CW) should do.
 */
enum class CwCommand : uint8_t {
    kIdle,  // stop adjusting
    kFill,  // add water
    kDrain  // remove water
};

/**
 * @brief What moves the pitch joint toward a target.
 */
enum class MotionMode : uint8_t {
    kTandem,    // actuator follows trajectory while CW trims toward target mass
    kCwPrimary  // CW moves free arm; actuator takes over near target
};

/**
 * @brief Calibration progress.
 */
enum class CalibrationStatus : uint8_t {
    kIdle,                   // never started -or- cancelled
    kSamplingLevel,          // level calibration: averaging torque at rest
    kMovingToA,              // two-angle calibration: moving to first angle
    kSamplingA,              // ... averaging at first angle
    kMovingToB,              // ... moving to second angle
    kSamplingB,              // ... averaging at second angle
    kFrictionMovingToStart,  // friction calibration: moving to lower angle
    kFrictionSweepUp,        // ... sweeping up
    kFrictionSweepDown,      // ... sweeping down
    kSucceeded,
    kFailed
};

bool IsCalibrationRunning(const CalibrationStatus& status);

/**
 * @brief Model values computed for logging.
 */
struct Libra2Diagnostics {
    std::optional<double> cw_mass;           // m_cw, Eq. 28 (kg)
    std::optional<double> torque_ext_g;      // τ_ext,g(θ), Eq. 36 (Nm)
    std::optional<double> cw_mass_tgt;       // m_cw,bal(θ_tgt), Eq. 38 (kg)
    std::optional<double> cw_mass_change;    // Δm_tgt, Eq. 40a (kg)
    std::optional<double> torque_ext_g_tgt;  // τ_ext,g(θ_tgt), Eq. 39 (Nm)
};

/**
 * @brief Constant-speed pitch move with a ramp of `ramp_dist` at each end.
 */
struct SweepRequest {
    double from{0.0};       // start angle (rad)
    double to{0.0};         // end angle (rad)
    double speed{0.0};      // speed between ramps, > 0 (rad/s)
    double ramp_dist{0.0};  // length of each ramp (rad)
};

/**
 * @brief LIBRA-II-specific motion command.
 */
struct Libra2Command : MotionCommand {
    explicit Libra2Command(const std::size_t& n_joints = 0)
        : MotionCommand(n_joints) {}

    std::optional<CwCommand> cw_command;         // none = no change
    std::optional<std::vector<double>> move_to;  // one-shot move (rad)
    std::optional<SweepRequest> sweep;           // one-shot pitch sweep
    bool stop_trajectory{false};                 // one-shot stop and hold
    Libra2Diagnostics diagnostics;
};

/**
 * @brief Values defining a CW model.
 */
struct CwModelParams {
    double pivot_dist{0.0};   // r_P at 0 L, A (m)
    double pivot_slope{0.0};  // r_P change per liter, B (m/L)
    double hang_offset{0.0};  // hang points (normal to arm) from O, q_P (m)
    double capacity{0.0};     // CW capacity (L)
};

bool IsSameCwModel(const CwModelParams& a, const CwModelParams& b);

/**
 * @brief Averaged measurements over one steady window.
 */
struct RestSample {
    double theta{0.0};            // mean measured angle (rad)
    double torque_actuator{0.0};  // mean measured actuator torque (Nm)
    double volume{0.0};           // mean CW volume (L)
};

//------------------------------------------------------------------------------
// !Calibration Record
//------------------------------------------------------------------------------

/**
 * @brief Arm model plus what it was computed from.
 */
struct ArmModelRecord {
    std::string source;               // "level", "two-angle", or "set"
    double level_torque{0.0};         // τ_g1,0 (Nm)
    double hang_torque{0.0};          // m_arm·h_1·g (Nm)
    CwModelParams cw_model;           // CW model used to compute it
    std::vector<RestSample> samples;  // raw; level: 1, two-angle: 2 (a, b)
};

/**
 * @brief Friction sweep results at one speed.
 */
struct FrictionPoint {
    double speed{0.0};   // v (rad/s)
    double drag{0.0};    // (τ_up − τ_down) / 2, averaged over bins (Nm)
    double spread{0.0};  // max − min of per-bin drag (Nm)
    int n_bins{0};       // bins sampled in both directions
};

/**
 * @brief Friction calibration result.
 */
struct FrictionResult {
    double coulomb{0.0};       // τ_c (Nm)
    double viscous{0.0};       // b (Nm·s/rad)
    double residual_rms{0.0};  // line fit residual (Nm)
    double angle_lo{0.0};      // sweep window start (rad)
    double angle_hi{0.0};      // sweep window end (rad)
    double volume{0.0};        // CW volume during sweeps (L)
    std::vector<FrictionPoint> points;
};

/**
 * @brief Everything worth saving about a calibrated controller.
 */
struct CalibrationRecord {
    // File metadata (filled in when saved/loaded)
    std::string saved_at;             // ISO 8601
    std::optional<double> extension;  // arm extension, entered by hand (mm)
    std::string note;

    // Controller constants when the record was made
    CwModelParams cw_model;
    double arm_inertia{0.0};  // (kg·m²)

    std::optional<ArmModelRecord> arm_model;  // none = not calibrated
    std::optional<FrictionResult> friction;   // none = not measured
};

}  // namespace Motion

//------------------------------------------------------------------------------
// !Pure Equations
//------------------------------------------------------------------------------

/**
 * @brief Stateless notebook equations. `cw_moment` is m_cw·r_P and
 *        `cw_hang_moment` is m_cw·q_P (both kg·m); see `CwModel`.
 */
namespace Libra2Model {

double CwMass(const double& volume);
double CwGravTorque(const double& cw_moment, const double& cw_hang_moment,
                    const double& grav, const double& theta);
double ArmGravTorque(const double& torque_meas, const double& cw_grav_torque);
std::optional<double> ArmLevelTorque(const double& arm_torque,
                                     const double& theta,
                                     const double& arm_hang_torque);
bool SolveTwoAngle(const double& arm_torque_a, const double& theta_a,
                   const double& arm_torque_b, const double& theta_b,
                   double& arm_level_torque, double& arm_hang_torque);
double NetGravTorque(const double& arm_level_torque,
                     const double& arm_hang_torque, const double& cw_moment,
                     const double& cw_hang_moment, const double& grav,
                     const double& theta);
double StabilityTorque(const double& arm_hang_torque,
                       const double& cw_hang_moment, const double& grav);
double TorqueCommand(const double& inertia, const double& inertia_rate,
                     const double& friction_viscous,
                     const double& friction_coulomb, const double& ref_acc,
                     const double& ref_vel, const double& net_grav_torque);
std::optional<double> BalanceCwMoment(const double& arm_level_torque,
                                      const double& arm_hang_torque,
                                      const double& grav, const double& theta);
double TargetNetGravTorque(const double& grav, const double& theta_tgt,
                           const double& cw_moment_eff,
                           const double& cw_moment_bal);
bool FitFrictionLine(const std::vector<double>& speeds,
                     const std::vector<double>& drags, double& coulomb,
                     double& viscous, double& residual_rms);

}  // namespace Libra2Model

//------------------------------------------------------------------------------
// !CW Model
//------------------------------------------------------------------------------

/**
 * @brief CW gravity moments and inertia as functions of CW mass, with r_P
 *        linear in CW volume.
 */
class CwModel {
  public:
    explicit CwModel(const double& cw_pivot_dist, const double& cw_pivot_slope,
                     const double& cw_hang_offset, const double& capacity);

    [[nodiscard]] bool IsValid() const {
        return error_.empty();
    }

    [[nodiscard]] const std::string& GetError() const {
        return error_;
    }

    [[nodiscard]] Motion::CwModelParams GetParams() const;
    [[nodiscard]] double GetCapacityMass() const;

    [[nodiscard]] double Moment(const double& mass) const;
    [[nodiscard]] double HangMoment(const double& mass) const;
    [[nodiscard]] double EffectiveMoment(const double& mass,
                                         const double& theta) const;
    [[nodiscard]] std::optional<double> MassForMoment(
        const double& moment, const double& theta,
        bool* clamped = nullptr) const;

    [[nodiscard]] double Inertia(const double& mass) const;
    [[nodiscard]] double InertiaSlope(const double& mass) const;

  private:
    [[nodiscard]] double PivotDist(const double& volume) const;

    double r_P_0_{0.0};    // r_P at 0 L, A (m)
    double dr_P_dV_{0.0};  // r_P change per liter, B (m/L)
    double q_P_{0.0};      // hang-point offset normal to arm, from O (m)
    double capacity_;      // CW capacity (L)
    std::string error_;
};

//------------------------------------------------------------------------------
// !Rest Sampler
//------------------------------------------------------------------------------

/**
 * @brief Averages pose, torque, and CW volume once all three have been steady
 *        for a full window. Any disturbance restarts the window.
 */
class RestSampler {
  public:
    void Reset();
    std::optional<Motion::RestSample> Add(const double& dt, const double& pos,
                                          const double& vel,
                                          const double& torque_actuator,
                                          const bool& trajectory_active,
                                          const std::optional<double>& volume);

  private:
    int count_{0};
    double t_elapsed_s_{0.0};  // seconds
    double anchor_theta_{0.0};
    double anchor_volume_{0.0};
    double sum_theta_{0.0};
    double sum_torque_{0.0};
    double sum_volume_{0.0};
};

//------------------------------------------------------------------------------
// !Class Declaration
//------------------------------------------------------------------------------

/**
 * @brief LIBRA-II pitch motion controller: gravity feedforward, automatic
 *        torque compensation, CW-primary mode, and arm model and friction
 *        calibrations.
 */
class Libra2MotionController : public AbstractMotionController {
  public:
    explicit Libra2MotionController(std::unique_ptr<Logger> logger,
                                    const double& cw_capacity,
                                    const double& torque_comp_lower_bound,
                                    const double& torque_comp_upper_bound,
                                    const double& torque_comp_slow_rate);
    explicit Libra2MotionController(
        std::unique_ptr<Logger> logger, const double& cw_pivot_dist,
        const double& cw_pivot_slope, const double& cw_hang_offset,
        const double& cw_capacity, const double& friction_coulomb,
        const double& friction_viscous, const double& arm_inertia,
        const double& torque_comp_lower_bound,
        const double& torque_comp_upper_bound,
        const double& torque_comp_slow_rate);

    // --- Control Cycle ---

    Motion::Libra2Command Update(const Motion::MotionState& state);

    // --- Settings (all lock) ---

    bool SetMotionMode(const Motion::MotionMode& mode);
    [[nodiscard]] Motion::MotionMode GetMotionMode() const;

    [[nodiscard]] bool IsMoving() const;

    void SetCwState(const double& volume, const double& flow);
    void EnableTorqueComp(const bool& enabled);
    void EnableInertiaFeedforward(const bool& enabled);
    bool SetTorqueCompBounds(const double& lower_bound,
                             const double& upper_bound);
    bool SetHandoffBand(const double& band);

    // --- Arm Model ---

    void SetArmModel(const double& arm_level_torque,
                     const double& arm_hang_torque);
    void ClearArmModel();

    [[nodiscard]] bool IsCalibrated() const;

    [[nodiscard]] double GetArmLevelTorque() const;
    [[nodiscard]] double GetArmHangTorque() const;
    [[nodiscard]] double ComputeNetGravTorque(const double& theta,
                                              const double& cw_mass) const;

    // --- Calibration ---

    bool StartLevelCalibration();
    bool StartTwoAngleCalibration(const double& angle_a, const double& angle_b);
    bool StartFrictionCalibration(const double& angle_a, const double& angle_b,
                                  const double& max_speed);
    void CancelCalibration();
    [[nodiscard]] Motion::CalibrationStatus GetCalibrationStatus() const;
    [[nodiscard]] std::string GetCalibrationMessage() const;

    // --- Calibration Record ---

    [[nodiscard]] Motion::CalibrationRecord GetCalibrationRecord() const;
    bool LoadCalibrationRecord(const Motion::CalibrationRecord& record);

  protected:
    // --- Overrides ---

    void OnTargetChanged() override;
    void OnStop() override;
    void OnReset() override;

  private:
    enum class CwPhase : uint8_t { kIdle, kCwMoving };

    struct AtcResult {
        double playback_rate{1.0};
        std::optional<Motion::CwCommand> cw_command;
    };

    /**
     * @brief State of a running friction calibration.
     */
    struct FrictionRun {
        double angle_lo{0.0};   // window start (rad)
        double angle_hi{0.0};   // window end (rad)
        double max_speed{0.0};  // caller's speed limit (rad/s)
        double volume{0.0};     // CW volume at start (L)
        std::size_t speed_idx{0};
        bool trajectory_seen{false};  // current sweep has started

        // Per-bin torque sums and counts for the current speed
        std::vector<double> up_sum;
        std::vector<double> down_sum;
        std::vector<int> up_count;
        std::vector<int> down_count;

        std::vector<Motion::FrictionPoint> points;
    };

    // --- Helper Functions ---

    AtcResult UpdateTorqueComp(const double& torque_magnitude,
                               const Motion::CwCommand& direction,
                               const bool& braking);
    std::optional<Motion::CwCommand> PredictiveCwCommand(
        const double& theta_tgt, const double& cw_mass,
        double* cw_mass_tgt) const;
    bool RunCwPrimary(const double& theta, const double& theta_tgt,
                      Motion::Libra2Command& command);

    void ComputeDiagnostics(const double& theta,
                            const std::optional<double>& theta_tgt,
                            Motion::Libra2Diagnostics& diagnostics) const;

    void RunCalibration(const Motion::MotionState& state, const double& theta,
                        const double& vel, const double& torque);
    void RunFrictionCalibration(const Motion::MotionState& state,
                                const double& theta, const double& vel,
                                const double& torque);
    void AddFrictionSample(const double& theta, const double& vel,
                           const double& torque, const bool& up,
                           const double& speed);
    bool FinishFrictionSpeed(const double& speed, std::string& error);
    void FinishFrictionCalibration();
    void BeginStage(const Motion::CalibrationStatus& status);
    void FinishCalibration(const bool& success, const std::string& message);
    [[nodiscard]] double SampleToArmTorque(
        const Motion::RestSample& sample) const;
    [[nodiscard]] bool RecomputeArmModel(const Motion::ArmModelRecord& record,
                                         double& arm_level_torque,
                                         double& arm_hang_torque) const;
    bool CheckStability(const double& arm_hang_torque);
    void CancelCalibrationLocked();

    [[nodiscard]] bool IsMovingLocked() const;

    // --- Data Members ---

    // Parameters (see `I_Controller-Code-Equivalencies.jpg`)
    CwModel cw_model_;
    double friction_coulomb_;  // τ_c (Nm)
    double friction_viscous_;  // b (Nm·s/rad)
    double arm_inertia_;       // arm only, about pitch joint O (kg·m²)

    // Arm model
    double arm_level_torque_{0.0};  // τ_g1,0 (Nm)
    double arm_hang_torque_{0.0};   // m_arm·h_1·g (Nm)
    bool calibrated_{false};
    std::string arm_source_;                       // see `ArmModelRecord`
    Motion::CwModelParams arm_cw_params_;          // CW model it was made with
    std::vector<Motion::RestSample> arm_samples_;  // raw samples behind it

    std::optional<Motion::FrictionResult> friction_result_;  // last one

    // CW state (from WaterController)
    std::optional<double> cw_vol_;   // V (L)
    std::optional<double> cw_mass_;  // m_cw, Eq. 28 (kg)
    double cw_flow_{0.0};            // V̇, + = filling (L/s)

    // Dynamics (Eq. 15), refreshed each cycle since the CW's share changes
    double inertia_{0.0};       // arm + CW (kg·m²)
    double inertia_rate_{0.0};  // from CW flow (kg·m²/s)
    bool inertia_ff_en_{true};  // off = inertia terms left out of Eq. 37

    // Mode and CW-primary state
    Motion::MotionMode mode_{Motion::MotionMode::kTandem};
    CwPhase cw_phase_{CwPhase::kIdle};
    bool cw_assist_done_{false};     // hand-off done; predictive CW off
    bool trajectory_active_{false};  // from last `Update()`

    double handoff_band_{Motion::kDefaultHandoffBand};  // (rad)

    // ATC
    bool atc_en_{false};
    bool movement_en_{true};

    double torque_comp_lower_bound_;      // "soft" limit (Nm)
    double torque_comp_upper_bound_;      // "hard" limit (Nm)
    const double torque_comp_slow_rate_;  // playback rate between limits

    // Calibration
    Motion::CalibrationStatus status_{Motion::CalibrationStatus::kIdle};
    bool two_angle_{false};
    double angle_a_{0.0};          // (rad)
    double angle_b_{0.0};          // (rad)
    double t_stage_s_{0.0};        // seconds
    Motion::RestSample sample_a_;  // two-angle: first angle's sample
    FrictionRun friction_run_;
    std::string calibration_message_;  // how the last calibration ended

    std::optional<double> pending_move_;                 // pitch angle (rad)
    std::optional<Motion::SweepRequest> pending_sweep_;  // next cycle's sweep
    bool pending_stop_{false};                           // next cycle's stop
    RestSampler sampler_;

    bool state_warned_{false};
};
